          "detailCopy": "Kombinasi sinergi dari Lumibiome Tone-Up Cream dan Lumibiome Glow-Up Serum yang dikembangkan melalui pendekatan ilmiah oleh pakar kosmetik dan riset formulasi lanjutan. Dirancang sebagai personalized skin system, formulanya membantu meningkatkan kecerahan, menghaluskan tekstur, serta menjaga keseimbangan dan kekuatan skin barrier untuk tampilan kulit yang lebih sehat, lembap, dan bercahaya alami.\n\nLumibiome Tone-Up Cream: Krim bertekstur ringan yang membantu mencerahkan, meratakan warna kulit, serta mendukung tampilan kulit sehat dan bercahaya alami. Diformulasikan dengan Microbiome Brightening & 5-Ceramide Barrier Technology, diperkaya prebiotik, postbiotik, dan 5-Ceramide. Perpaduan Niacinamide, Panax Ginseng, dan Centella Extract membantu mencerahkan dan menjaga kenyamanan kulit.\n\nLumibiome Glow-Up Serum: Serum bertekstur ringan yang diformulasikan untuk membantu meningkatkan kecerahan kulit, memperbaiki tampilan tekstur, dan mendukung tampilan kulit yang sehat bercahaya. Diformulasikan dengan Postbiotic Radiance & PDRN Regeneration Technology. Mengandung PDRN Rice yang membantu mendukung elastisitas kulit serta menyamarkan tampilan garis halus. Kombinasi TX-Pep dan Niacinamide membantu meratakan dan meningkatkan warna kulit.",
