        "shortDescription": "BEAUTYNATURE memadukan personal care dan home wellness yang terinspirasi dari kesegaran alam. Portofolio terdiri dari 14 produk yang mencakup perawatan rambut, tubuh, kebersihan mulut serta tangan, pengharum ruangan, dan lima varian aromaterapi. Fokusnya menghubungkan kebersihan serta kelembapan dengan pengalaman aroma untuk menemani berbagai momen sehari-hari.",
        "longDescription": "BEAUTYNATURE memadukan personal care dan home wellness yang terinspirasi dari kesegaran alam. Portofolio terdiri dari 14 produk yang mencakup perawatan rambut, tubuh, kebersihan mulut serta tangan, pengharum ruangan, dan lima varian aromaterapi. Fokusnya menghubungkan kebersihan serta kelembapan dengan pengalaman aroma untuk menemani berbagai momen sehari-hari.\n\nPure Series mencakup pasta gigi, sabun tangan, dan semprotan tangan, sedangkan Bloom Series menghadirkan sampo serta kondisioner. Dew Series terdiri dari body wash dan body lotion, dengan Natural Dew Body Lotion menonjolkan 5X Moisture Support System. Pine & Forest Series melengkapi suasana ruang serta ritual aroma melalui diffuser, room spray, Forest Relief, Harmony, Calm Night, Cozy Sleep, dan Fresh Comfort.\n\nArsitektur seri\n\n• Pure Series — Kebersihan & Perlindungan: Naturally Clean. Comfortably Protected.\n\n• Bloom Series — Perawatan Rambut: Where Healthy Hair Comes Into Bloom.\n\n• Dew Series — Kulit & Tubuh: Nature's Moisture. Everyday Comfort.\n\n• Pine & Forest — Home Wellness & Aromaterapi: Bring The Forest Home.\n\nWellness Collection Guide\n\n| Momen | Varian | Karakter pengalaman aroma | |---|---|---| | Pagi–siang | Fresh Comfort | Fresh & Energizing — citrus segar untuk membangkitkan semangat. | | Siang–sore | Harmony | Balanced & Comforting — suasana seimbang untuk tetap fokus. | | Sore–malam | Forest Relief | Relaxing & Grounding — momen melepaskan penat setelah aktivitas. | | Menjelang tidur | Calm Night | Calm & Peaceful — suasana malam yang tenang. | | Saat tidur | Cozy Sleep | Cozy & Comforting — suasana nyaman saat tidur. |",
