          "shortDescription": "PHYTOSYNC™ mengusung sistem formulasi berbasis superfood phytoactives yang memadukan bahan botani dan bahan aktif perawatan kulit. Pendekatannya menempatkan kombinasi bahan sebagai dasar untuk menjawab kebutuhan kulit yang berbeda, mulai dari kecerahan, kenyamanan, dan kelembapan hingga perawatan elastisitas serta perlindungan harian. Portofolio PHYTOSYNC terdiri dari enam serum dengan fokus berbeda dan satu hybrid sunscreen.",
